select id, order_id, product_id, quantity, unit_price, last_value(unit_price, true) over (partition by product_id, order_id order by unit_price asc, id asc rows between unbounded preceding and current row) as last_known_unit_price, lead(quantity, 2) over (partition by product_id, order_id order by quantity asc, id asc) as next_quantity, dense_rank() over (partition by order_id order by unit_price asc) as unit_price_dense_rank, sum(unit_price) over w_hist as cumulative_unit_price, round(quantity / sum(quantity) over (partition by order_id), 4) as quantity_share from order_items window w_hist as (order by unit_price asc, id asc rows between unbounded preceding and current row);
